<?php
/** Printable shipment summary for staff and administrators. */
session_start();
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/function/shipment_common.php';
[$userId, $fullName, $role] = requireStaffOrAdmin($conn);
$id = (int)($_GET['id'] ?? 0);
$st = $conn->prepare('SELECT s.*, c.client_name, c.contact_person, c.email AS client_email, c.phone AS client_phone, u.full_name AS staff_name FROM shipments s JOIN clients c ON c.client_id=s.client_id LEFT JOIN users u ON u.user_id=s.assigned_staff_id WHERE s.shipment_id=?');
$st->execute([$id]);
$ship = $st->fetch();
if (!$ship) { http_response_code(404); exit('Shipment not found.'); }
$st = $conn->prepare('SELECT * FROM customs_processing WHERE shipment_id=? ORDER BY customs_id DESC LIMIT 1'); $st->execute([$id]); $customs = $st->fetch() ?: [];
$st = $conn->prepare('SELECT * FROM deliveries WHERE shipment_id=? ORDER BY delivery_id DESC LIMIT 1'); $st->execute([$id]); $delivery = $st->fetch() ?: [];
$st = $conn->prepare('SELECT * FROM containers WHERE shipment_id=? ORDER BY container_id'); $st->execute([$id]); $containers = $st->fetchAll();
$st = $conn->prepare('SELECT doc_type, file_path, uploaded_at FROM shipment_documents WHERE shipment_id=? ORDER BY uploaded_at DESC, document_id DESC'); $st->execute([$id]); $documents = $st->fetchAll();
$st = $conn->prepare('SELECT stage, remarks, updated_at FROM shipment_status_updates WHERE shipment_id=? ORDER BY updated_at DESC, update_id DESC'); $st->execute([$id]); $timeline = $st->fetchAll();
$st = $conn->prepare('SELECT billing_no, billing_date, due_date, total_amount, payment_status FROM billings WHERE shipment_id=? ORDER BY billing_id DESC'); $st->execute([$id]); $billings = $st->fetchAll();
function summaryRows(array $fields): void { foreach ($fields as $label => $value): if ($value === null || $value === '') $value = '—'; ?><div class="field"><dt><?= e($label) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach; }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($ship['reference_no']) ?> Shipment Summary | AstraTrack</title>
