ad h1{font-size:23px}}@media(max-width:460px){.grid,.two{grid-template-columns:1fr}.head{flex-direction:column;gap:10px}.toolbar{padding:10px}.toolbar a,.toolbar button{flex:1;text-align:center}}@media print{@page{size:A4;margin:14mm}body{background:#fff;font-size:10pt}.toolbar{display:none}.sheet{max-width:none;margin:0;padding:0;border:0;border-radius:0;box-shadow:none}.section{break-inside:avoid}.head{break-inside:avoid}.table th{background:#f3f6f9!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style></head><body><nav class="toolbar"><a href="shipment_view.php?id=<?= $id ?>">Back to shipment</a><button class="primary" onclick="window.print()">Print / Save PDF</button></nav>
<main class="sheet"><header class="head"><div><div class="brand">AstraTrack · Shipment Summary</div><h1><?= e($ship['reference_no']) ?></h1><p class="sub"><?= e(ucfirst($ship['transaction_type'])) ?> · <?= e(ucfirst($ship['mode'])) ?> · Created <?= e(fmtDate($ship['created_at'])) ?></p></div><span class="status"><?= e($ship['current_status']) ?><?= $ship['archived_at'] ? ' · Archived' : '' ?></span></header>
<section class="section"><h2>Shipment and Client</h2><dl class="grid"><?php summaryRows(['Client' => $ship['client_name'], 'Assigned Staff' => $ship['staff_name'] ?: 'Unassigned', 'Client Contact' => $ship['contact_person'], 'Client Email' => $ship['client_email'], 'Client Phone' => $ship['client_phone'], 'Shipment Remarks' => $ship['remarks']]); ?></dl></section>
<section class="section"><h2>Key Dates</h2><dl class="grid two"><?php summaryRows(['Estimated Arrival' => fmtDate($ship['eta_date']), 'First Free Day' => fmtDate($ship['first_free_day']), 'Delivery Due' => fmtDate($ship['delivery_due_date']), 'Actual Arrival' => fmtDate($ship['actual_arrival_date'])]); ?></dl></section>
<section class="section"><h2>Cargo and Route</h2><dl class="grid"><?php summaryRows(['B/L or AWB' => $ship['bl_awb_no'], 'Shipper' => $ship['shipper_name'], 'Consignee' => $ship['consignee_name'], 'Vessel / Flight' => $ship['vessel_or_flight'], 'Port of Loading' => $ship['port_of_loading'], 'Port of Discharge' => $ship['port_of_discharge'], 'HS Code' => $ship['hs_code'], 'Incoterm' => $ship['incoterm'], 'Packages' => $ship['total_packages'], 'Gross Weight (kg)' => $ship['total_gross_weight'], 'Measurement (CBM)' => $ship['measurement_cbm']]); ?></dl></section>
<section class="section"><h2>Invoice and Values</h2><dl class="grid"><?php summaryRows(['Invoice No.' => $ship['invoice_no'], 'Currency' => $ship['currency'], 'Invoice Value' => $ship['invoice_value'], 'Freight Amount' => $ship['freight_amount'], 'FOB Value' => $ship['fob_value']]); ?></dl></section>
<section class="section"><h2>Containers (<?= count($containers) ?>)</h2><?php if ($containers): ?><table class="table"><thead><tr><th>Container No.</th><th>Size / Type</th><th>Seal No.</th></tr></thead><tbody><?php foreach ($containers as $row): ?><tr><td><?= e($row['container_no']) ?></td><td><?= e($row['size_type'] ?: '—') ?></td><td><?= e($row['seal_no'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><p class="empty">No containers recorded.</p><?php endif; ?></section>
<section class="section"><h2>Customs Processing</h2><dl class="grid"><?php summaryRows(['Entry No.' => $customs['entry_no'] ?? null, 'Declaration Type' => $customs['declaration_type'] ?? null, 'Lodgement Date' => fmtDate($customs['lodgement_date'] ?? null), 'Assessment' => $customs['assessment_status'] ?? null, 'Duties and Taxes' => $customs['duties_taxes_amount'] ?? null, 'Duties Paid' => fmtDate($customs['duties_paid_date'] ?? null), 'Clearance Date' => fmtDate($customs['clearance_date'] ?? null), 'Examination Lane' => $customs['examination_lane'] ?? null, 'Remarks' => $customs['customs_remarks'] ?? null]); ?></dl></section>
<section class="section"><h2>Delivery</h2><dl class="grid"><?php summaryRows(['Status' => $delivery['status'] ?? null, 'Scheduled Date' => fmtDate($delivery['scheduled_date'] ?? null), 'Scheduled Time' => $delivery['scheduled_time'] ?? null, 'Trucker' => $delivery['trucker'] ?? null, 'Driver' => $delivery['driver_name'] ?? null, 'Plate No.' => $delivery['plate_no'] ?? null, 'Delivery Address' => $delivery['delivery_address'] ?? null, 'Receiving Contact' => $delivery['receiving_contact'] ?? null, 'Delivered Date' => fmtDate($delivery['delivered_date'] ?? null)]); ?></dl></section>
<section class="section"><h2>Documents (<?= count($documents) ?>)</h2><?php if ($documents): ?><table class="table"><thead><tr><th>Type</th><th>File</th><th>Uploaded</th></tr></thead><tbody><?php foreach ($documents as $row): ?><tr><td><?= e($row['doc_type']) ?></td><td><?= e(basename($row['file_path'])) ?></td><td><?= e(fmtDateTime($row['uploaded_at'])) ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><p class="empty">No documents uploaded.</p><?php endif; ?></section>
<section class="section"><h2>Billing</h2><?php if ($billings): ?><table class="table"><thead><tr><th>Billing No.</th><th>Billing Date</th><th>Due Date</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach ($billings as $row): ?><tr><td><?= e($row['billing_no']) ?></td><td><?= e(fmtDate($row['billing_date'])) ?></td><td><?= e(fmtDate($row['due_date'])) ?></td><td><?= e(number_format((float)$row['total_amount'], 2)) ?></td><td><?= e(ucfirst($row['payment_status'])) ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><p class="empty">No billing record linked.</p><?php endif; ?></section>
<section class="section"><h2>Status History</h2><?php if ($timeline): ?><div class="timeline"><?php foreach ($timeline as $event): ?><div class="event"><strong><?= e($event['stage']) ?></strong><small><?= e(fmtDateTime($event['updated_at'])) ?></small><?php if ($event['remarks']): ?><div><?= e($event['remarks']) ?></div><?php endif; ?></div><?php endforeach; ?></div><?php else: ?><p class="empty">No status history recorded.</p><?php endif; ?></section>
<footer class="footer">Printed from AstraTrack by <?= e($fullName) ?> · <?= e(date('M d, Y g:i A')) ?></footer></main></body></html>
